/**
 * RBQ-Draw-Plugins Sub-Plugin: 摸鱼悬浮球 (Slack-off Floating Ball)
 * Version: 1.1.2
 * Author: TTWP-09
 * Description: 自定义生图触发器的悬浮球样式，支持超可爱的摸鱼猫咪与小孩（愣住）表情，可在通用设置中自由切换。
 */
(function(RBQ, $, toastr) {
    'use strict';

    const STORAGE_KEY = 'rbq_custom_floating_icon_choice';
    const STYLE_ID = 'rbq-sdt-custom-float-style';
    const SETTING_CONTAINER_ID = 'rbq-custom-floating-icon-setting';

    const ICONS = {
        cat: {
            id: 'cat',
            name: '摸鱼猫咪',
            filter: 'drop-shadow(0 4px 10px rgba(255, 158, 187, 0.45))',
            hoverFilter: 'drop-shadow(0 6px 14px rgba(255, 158, 187, 0.65))',
            hoverTransform: 'scale(1.12) rotate(4deg)',
            activeFilter: 'drop-shadow(0 2px 6px rgba(255, 158, 187, 0.3))',
            image: 'data:image/png;base64,'
        },
        kid: {
            id: 'kid',
            name: '小孩',
            filter: 'drop-shadow(0 4px 10px rgba(0, 0, 0, 0.45))',
            hoverFilter: 'drop-shadow(0 6px 14px rgba(0, 0, 0, 0.65))',
            hoverTransform: 'scale(1.12) rotate(-4deg)',
            activeFilter: 'drop-shadow(0 2px 6px rgba(0, 0, 0, 0.3))',
            image: 'data:image/png;base64,'
        }
    };

    function getStoredChoice() {
        try {
            if (window.RBQ && window.RBQ.api && window.RBQ.api.getSettings) {
                const s = window.RBQ.api.getSettings();
                if (s.floatingIconStyle && ICONS[s.floatingIconStyle]) {
                    return s.floatingIconStyle;
                }
            }
        } catch (_) {}
        try {
            const local = localStorage.getItem(STORAGE_KEY);
            if (local && ICONS[local]) return local;
        } catch (_) {}
        return 'cat';
    }

    function setStoredChoice(choice) {
        try {
            localStorage.setItem(STORAGE_KEY, choice);
        } catch (_) {}
        try {
            if (window.RBQ && window.RBQ.api && window.RBQ.api.getSettings) {
                const s = window.RBQ.api.getSettings();
                s.floatingIconStyle = choice;
                if (window.RBQ.api.saveSettings) {
                    window.RBQ.api.saveSettings();
                }
            }
        } catch (_) {}
    }

    function applyIconStyle(choice) {
        const icon = ICONS[choice] || ICONS.cat;
        let style = document.getElementById(STYLE_ID);
        if (!style) {
            style = document.createElement('style');
            style.id = STYLE_ID;
            document.head.appendChild(style);
        }
        style.innerHTML = [
            '#st-scene-trigger-floating-toggle {',
            '    background: transparent !important;',
            '    border: none !important;',
            '    border-radius: 0 !important;',
            '    box-shadow: none !important;',
            '    backdrop-filter: none !important;',
            '    -webkit-backdrop-filter: none !important;',
            '    outline: none !important;',
            '    overflow: visible !important;',
            '    display: flex !important;',
            '    align-items: center !important;',
            '    justify-content: center !important;',
            '    transform: none;',
            '    will-change: transform, filter;',
            '    transition: transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275), filter 0.25s ease !important;',
            '    filter: ' + icon.filter + ' !important;',
            '}',
            '#st-scene-trigger-floating-toggle:hover,',
            '#st-scene-trigger-floating-toggle:not(.st-scene-trigger-hidden):hover {',
            '    transform: ' + icon.hoverTransform + ' !important;',
            '    filter: ' + icon.hoverFilter + ' !important;',
            '}',
            '#st-scene-trigger-floating-toggle:active,',
            '#st-scene-trigger-floating-toggle:not(.st-scene-trigger-hidden):active {',
            '    transform: scale(0.92) !important;',
            '    filter: ' + icon.activeFilter + ' !important;',
            '}',
            '#st-scene-trigger-floating-toggle.st-scene-trigger-hidden,',
            '#st-scene-trigger-floating-toggle[style*="display: none"] {',
            '    display: none !important;',
            '    visibility: hidden !important;',
            '    opacity: 0 !important;',
            '    pointer-events: none !important;',
            '    filter: none !important;',
            '}',
            '#st-scene-trigger-floating-toggle .st-scene-trigger-kite-icon {',
            '    display: none !important;',
            '}',
            '#st-scene-trigger-floating-toggle::after {',
            '    content: "";',
            '    display: block;',
            '    width: 100%;',
            '    height: 100%;',
            '    background-image: url("' + icon.image + '");',
            '    background-size: contain;',
            '    background-position: center;',
            '    background-repeat: no-repeat;',
            '}'
        ].join('\n');
    }

    function injectSettingUi() {
        let container = document.getElementById(SETTING_CONTAINER_ID);
        if (!container) {
            const target = document.querySelector('.st-scene-trigger-field[data-setting-key="showFloatingButton"]');
            if (!target || !target.parentNode) return false;

            const currentChoice = getStoredChoice();
            container = document.createElement('label');
            container.className = 'st-scene-trigger-field';
            container.id = SETTING_CONTAINER_ID;
            container.innerHTML = [
                '<span>悬浮球样式</span>',
                '<select id="rbq-custom-floating-icon-select">',
                '    <option value="cat"' + (currentChoice === 'cat' ? ' selected' : '') + '>摸鱼猫咪</option>',
                '    <option value="kid"' + (currentChoice === 'kid' ? ' selected' : '') + '>小孩</option>',
                '</select>'
            ].join('');

            target.parentNode.insertBefore(container, target.nextSibling);

            const select = container.querySelector('#rbq-custom-floating-icon-select');
            if (select) {
                select.addEventListener('change', function(e) {
                    const val = e.target.value;
                    setStoredChoice(val);
                    applyIconStyle(val);
                    if (typeof toastr !== 'undefined' && toastr && toastr.success) {
                        toastr.success('悬浮球样式已切换为: ' + (ICONS[val] ? ICONS[val].name : val), '摸鱼悬浮球');
                    }
                });
            }
        } else {
            const select = container.querySelector('#rbq-custom-floating-icon-select');
            if (select) {
                const currentChoice = getStoredChoice();
                if (select.value !== currentChoice) {
                    select.value = currentChoice;
                }
            }
        }
        return true;
    }

    // Apply style immediately
    const initialChoice = getStoredChoice();
    applyIconStyle(initialChoice);

    // Initial setting injection
    if (!injectSettingUi()) {
        const timer = setInterval(function() {
            if (injectSettingUi()) clearInterval(timer);
        }, 500);
        setTimeout(function() { clearInterval(timer); }, 30000);
    }

    // Ensure injection when user interacts or opens modal
    document.addEventListener('click', function() {
        setTimeout(injectSettingUi, 50);
    });

    console.info('[RBQ Plugin] Slack-off Floating Ball (摸鱼悬浮球) v1.1.2 loaded.');
})(window.RBQ, typeof jQuery !== 'undefined' ? jQuery : window.$, typeof toastr !== 'undefined' ? toastr : window.toastr);
